import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%AC%E3%82%B9%E3%83%95%E3%82%A1%E3%83%B3%E3%83%92%E3%83%BC%E3%82%BF%E3%83%BC.html","title":"ガスファンヒーター","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.19,"words":358},"filePathRelative":"ガスファンヒーター.md"}`),a={name:`ガスファンヒーター.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ガスファンヒーター" tabindex="-1"><a class="header-anchor" href="#ガスファンヒーター"><span>ガスファンヒーター</span></a></h1><p><a href="./グッズ関連.html">グッズ関連</a></p><p>我が家はダイニング・キッチンが11畳で、ここにはエアコンが無い。 そこで仕事部屋に大型のエアコンをつけていてそれでリビングも兼用という感じにしているのだが、 夏は多少暑く、冬は多少寒い。</p><p>夏は暑い時には仕事部屋で食事をすればいいか、と思っていて、わざわざエアコンをつけようという気は起こらないが、 暖房は買ってもいいかなぁ、という気はしていた。</p><p>ただ冬は奄美に居る事が多くてあまりこの家には居ないので、正直そんなには使わない。 むしろ奄美の宿に暖房欲しい…</p><p>そんなには使わないが、大して高いものでも無くそこまで邪魔なものでも無いので買ってもいいかな、という気もする、という微妙なラインだったが、 今年は寒くなるのが早かった(2025年10月25日現在、まぁまぁ寒い）ので、買う事にした。</p><h2 id="リンナイ-木造11畳-コンクリート15畳-rc-n356e-13a" tabindex="-1"><a class="header-anchor" href="#リンナイ-木造11畳-コンクリート15畳-rc-n356e-13a"><span>リンナイ 木造11畳/コンクリート15畳 RC-N356E/13A</span></a></h2><p><a href="https://www.yodobashi.com/product/100000001004986271/" target="_blank" rel="noopener noreferrer">ヨドバシ.com - リンナイ Rinnai ガスファンヒーター 木造11畳/コンクリート15畳 都市ガス用 RC-N356E/13A 通販【全品無料配達】</a></p><h3 id="購入-2025-10-25-土" tabindex="-1"><a class="header-anchor" href="#購入-2025-10-25-土"><span>購入 2025-10-25 (土)</span></a></h3><p>ヨドバシで購入。 28660円だった。ガスホースは3mを購入してこちらは1万円くらい。2mでも平気そうだったが、ギリギリだったので少し余裕を持って3mにした。</p><p>当初は楽天とヨドバシを知らべて楽天の方が新しそうに見えたが、型番でググってみると形が少し違うだけの同じモデルとの事で、 量販店かネット通販かの違いらしい、と知り、値段も2000円くらいしか違わなかったのでヨドバシで購入。</p><p>26日の18時ころ届くが元栓の形が違った(´・ω・｀)</p><h3 id="なかなかいいね-2025-10-27-月" tabindex="-1"><a class="header-anchor" href="#なかなかいいね-2025-10-27-月"><span>なかなかいいね！ 2025-10-27 (月)</span></a></h3><p>アダプタが届いたのでつけてみた。今日はそんなに寒くは無いんだが、夕方から少し冷えてきたので。 なんか自分の知ってるガスファンヒーターよりもおだやかというか、いい感じにあったかくなる。 足元に風を当てていてもそこまで熱くなくていい感じに温かい。</p><p>ガステーブルは少し長くて邪魔かも？と思いつつ3mにしたが、むしろ少し短いくらいだった。3mでもいいがもっと長くても良かった。 ただ座る場所を変更したらいい感じになった。</p><p>15畳用はでかいのか？と思ったが割とコンパクトで取り回しもいいし、これで良かった。</p><p>やはりリビングを温められる、というのはいいなぁ、と使ってみて思った。仕事部屋のエアコンと合わせて、室内全体が暖かくなった。 温風に直接あたって温かいのでは無く、部屋自体があったかい。裸足でもいいか、って思える感じにあったかい。</p><p>買ってよかった。というかもっと早く買うべきだったな。</p><h3 id="少し寒い日が劇的に改善された-2025-10-31-金" tabindex="-1"><a class="header-anchor" href="#少し寒い日が劇的に改善された-2025-10-31-金"><span>少し寒い日が劇的に改善された 2025-10-31 (金)</span></a></h3><p>暖房をつけると2分くらいで部屋自体が温まる。出ている温風にあたると温かいのでは無く部屋自体の冷え込みが取り払われる感じ。 どういうメカニズムなのかは良く分からないが、凄くいい感じだ。</p><p>リビングが快適になった結果、仕事部屋よりリビングに居る事が増えてきた。つまりエアコンより快適という事のようだ。</p><p>別にまだそこまで冬では無いので服をもっと着たりすれば平気な程度の寒さなのだが、 なんか部屋が寒くて活動的でなくなる感じが取り払われた。 これはいい。もっと早く買うべきだった。</p><h3 id="変換アダプターの外し方-2026-05-12-火" tabindex="-1"><a class="header-anchor" href="#変換アダプターの外し方-2026-05-12-火"><span>変換アダプターの外し方 2026-05-12 (火)</span></a></h3><p>ストーブを片付けよう、という事で変換アダプターを外そうとしたがはずれない。 途中まではするっと動くが、そこから先が動かない。</p><p>結局ラジオペンチを間に挟んでてこの原理で外す。</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};